import React, { useEffect, useState } from 'react';
import Container from 'react-bootstrap/Container';
import Row from 'react-bootstrap/Row';
import Col from 'react-bootstrap/Col';
import { Link, useLocation } from 'react-router-dom';
import noProfile from '../../../assets/images/noprofile_images.jpg';
import { Table } from 'react-bootstrap';
import moment from 'moment';
// import CompanyDetails from '../../components/Atom/CompanyDetails';
import _ from "lodash";
import { baseURL } from '../../../api/ApiConfig';
import CompanyDetails from '../../../components/Atom/CompanyDetails';
import { usePageTitle } from '../../../hooks';

function Index() {


    usePageTitle({
        title: 'E-mark',
        breadCrumbItems: [
            {
                path: '/e-mark/home',
                label: 'E-mark',
            },
            {
                path: '/e-mark/biodata',
                label: 'Biodata',
                active: true,
            },
        ],
    });

    const baseUrl = baseURL || "https://crmapi.repatriatepeoples.com";
    // const baseUrl = baseURL ;

    const { state } = useLocation();

    console.log("state");
    console.log(state);

    const [stateVal, setStateVal] = useState({})

    useEffect(() => {
        if (state != undefined && state != null) {
            setStateVal(state || {});
        }
        window.scrollTo(0, 0);
    }, [state]);

    const staffBiodata = {
        profileImg: `${baseUrl}${stateVal?.personalInfo?.staffProfileImageName}`,
        staffDetails: {
            employeeName: `${stateVal?.employeeName || ''}`,
            dob: `${moment(stateVal?.personalInfo?.dob).format("DD-MM-YYYY")}`,
            age: `${stateVal?.age || '22'}`,
            address: `${stateVal?.addressI || ''}, ${stateVal?.addressII}`,
            aadharNumber: `${stateVal?.aadharNumber || ''}`,
            panCardNumber: `${stateVal?.panCardNumber || ''}`,
            mobileNumber: `${stateVal?.mobileNumber || ''}`,
            mailId: `${stateVal?.emailId || ''}`,
            employmentExperience: stateVal?.staffExperiance
        }
    };

    const footerFields = [['Name', 'Signature', 'Date']];

    const underlineStyle = (text) => ({
        display: 'inline-block',
        textAlign: 'center',
        borderBottom: '2px solid black',
        width: `${text.length * 12}px`,
        lineHeight: 1.5,
        verticalAlign: 'bottom',
    });

    return (
        <Container className="letter-container my-4 p-4 bg-white" style={{ maxWidth: '800px' }}>
            <div className='mb-3'>
                <CompanyDetails fontSize="13px" imgSize="200px"
                    classStyle="d-flex justify-content-center flex-column align-items-center" />
            </div>

            <div style={{ marginBottom: '10px' }}>
                <Row className="mt-3 mb-1">
                    <Row className="text-center">
                        <h3 style={{ color: 'black' }}>EMARK DATA</h3>
                        <p style={{ color: 'black', marginTop: '5px' }}>
                            (To be filled in by the candidate in his / her own handwritting)
                        </p>
                    </Row>
                </Row>
                <Row className="mt-3 mb-1" style={{ flex: 1, justifyContent: 'space-between' }}>
                    <Col style={{ flex: 0.7 }}>
                        <Row style={{ flex: 1, marginTop: '40px' }}>
                            <p style={{ color: 'black' }}>
                                <span style={{ fontWeight: 'bold' }}>1. NAME: </span>
                                <span style={underlineStyle(staffBiodata.staffDetails?.employeeName || '')}>{staffBiodata.staffDetails?.employeeName || ''}
                                </span>{' '}
                            </p>
                        </Row>
                        <Row style={{ flex: 1 }}>
                            <p style={{ color: 'black' }}>
                                <span style={{ fontWeight: 'bold' }}>2. DATE OF BIRTH: </span>
                                <span style={underlineStyle(staffBiodata.staffDetails?.dob || '')}>
                                    {staffBiodata.staffDetails?.dob || ''}
                                </span>{' '}
                                <span style={{ fontWeight: 'bold' }}> AGE: </span>
                                <span style={underlineStyle(staffBiodata.staffDetails?.dob || '')}>
                                    {staffBiodata.staffDetails?.age || ''}
                                </span>{' '}
                            </p>
                        </Row>
                    </Col>
                    <Col style={{ flex: 0.3 }}>
                        <img
                            src={staffBiodata?.profileImg || noProfile}
                            alt="profile image"
                            crossOrigin='anonymous'
                            style={{ width: '100%', height: '160px', objectFit: 'contain' }}
                            onError={(e) => {
                                e.target.onerror = null;
                                e.target.src = noProfile;
                            }}
                        />
                    </Col>
                </Row>
                {/* address */}
                <Row className="mt-3 mb-1">
                    <Row className="" style={{ alignItems: 'center', justifyContent: 'space-around' }}>
                        <Col xl={12}>
                            <p style={{ color: '#000', fontWeight: 'bold', fontSize: '16px' }}>
                                3. ADDRESS FOR COMMUNICATION{' '}
                            </p>
                        </Col>
                    </Row>
                    <Row className="mx-2" style={{ alignItems: 'center', justifyContent: 'space-around' }}>
                        <Col style={{ flex: 0.41 }}>
                            <p style={{ color: '#000', fontWeight: 'semi-bold', fontSize: '16px' }}>a. Address</p>
                        </Col>
                        <Col style={{ flex: 0.1 }}>
                            <p style={{ color: '#000', fontWeight: 'bold', fontSize: '16px' }}>:</p>
                        </Col>
                        <Col style={{ flex: 0.49, textAlign: 'left' }}>
                            <p style={{ color: '#000', fontWeight: 'bold', fontSize: '16px', textAlign: 'left' }}>
                                {staffBiodata.staffDetails?.address || ''}
                            </p>
                        </Col>
                    </Row>
                    <Row className="mx-2" style={{ alignItems: 'center', justifyContent: 'space-around' }}>
                        <Col style={{ flex: 0.41 }}>
                            <p style={{ color: '#000', fontWeight: 'semi-bold', fontSize: '16px' }}>b. Aadhar Number</p>
                        </Col>
                        <Col style={{ flex: 0.1 }}>
                            <p style={{ color: '#000', fontWeight: 'bold', fontSize: '16px' }}>:</p>
                        </Col>
                        <Col style={{ flex: 0.49, textAlign: 'left' }}>
                            <p style={{ color: '#000', fontWeight: 'bold', fontSize: '16px', textAlign: 'left' }}>
                                {staffBiodata.staffDetails?.aadharNumber || ''}
                            </p>
                        </Col>
                    </Row>
                    <Row className="mx-2" style={{ alignItems: 'center', justifyContent: 'space-around' }}>
                        <Col style={{ flex: 0.41 }}>
                            <p style={{ color: '#000', fontWeight: 'semi-bold', fontSize: '16px' }}>c. PAN Number</p>
                        </Col>
                        <Col style={{ flex: 0.1 }}>
                            <p style={{ color: '#000', fontWeight: 'bold', fontSize: '16px' }}>:</p>
                        </Col>
                        <Col style={{ flex: 0.49, textAlign: 'left' }}>
                            <p style={{ color: '#000', fontWeight: 'bold', fontSize: '16px', textAlign: 'left' }}>
                                {staffBiodata.staffDetails?.panCardNumber || ''}
                            </p>
                        </Col>
                    </Row>
                </Row>
                {/* mobile number */}
                <Row className="mt-3 mb-1">
                    <Row className="" style={{ alignItems: 'center', justifyContent: 'space-around' }}>
                        <Col xl={12}>
                            <p style={{ color: '#000', fontWeight: 'bold', fontSize: '16px' }}>
                                4. CONTACT DETAILS
                            </p>
                        </Col>
                    </Row>
                    <Row className="mx-2" style={{ alignItems: 'center', justifyContent: 'space-around' }}>
                        <Col style={{ flex: 0.41 }}>
                            <p style={{ color: '#000', fontWeight: 'semi-bold', fontSize: '16px' }}>a. Mobile Number</p>
                        </Col>
                        <Col style={{ flex: 0.1 }}>
                            <p style={{ color: '#000', fontWeight: 'bold', fontSize: '16px' }}>:</p>
                        </Col>
                        <Col style={{ flex: 0.49, textAlign: 'left' }}>
                            <p style={{ color: '#000', fontWeight: 'bold', fontSize: '16px', textAlign: 'left' }}>
                                {staffBiodata.staffDetails?.mobileNumber || ''}
                            </p>
                        </Col>
                    </Row>
                    <Row className="mx-2" style={{ alignItems: 'center', justifyContent: 'space-around' }}>
                        <Col style={{ flex: 0.41 }}>
                            <p style={{ color: '#000', fontWeight: 'semi-bold', fontSize: '16px' }}>b. E-mail ID</p>
                        </Col>
                        <Col style={{ flex: 0.1 }}>
                            <p style={{ color: '#000', fontWeight: 'bold', fontSize: '16px' }}>:</p>
                        </Col>
                        <Col style={{ flex: 0.49, textAlign: 'left' }}>
                            <p style={{ color: '#000', fontWeight: 'bold', fontSize: '16px', textAlign: 'left' }}>
                                {staffBiodata.staffDetails?.mailId || ''}
                            </p>
                        </Col>
                    </Row>
                </Row>
                {/* Employment Experience */}
                <Row className="mt-3 mb-1">
                    <p style={{ color: '#000', fontWeight: 'bold', fontSize: '16px' }}>5. EMPLOYMENT EXPERIENCE</p>
                    <div className="border rounded p-3 bg-light mt-4">
                        <h4 className="fw-bold mb-3">Work Experience</h4>
                        {staffBiodata?.staffDetails?.employmentExperience?.map((comp, idx) => (
                            <div className='mb-3' key={idx}>
                                <h4 className='text-start'>{comp?.title}
                                    <br />
                                    <div className='text-start' style={{ marginTop: "6px", fontSize: "15px" }}>{`(${moment(comp?.dateOfJoining || null).format("DD-MM-YYYY")} - ${comp?.dateOfReleving ? moment(comp?.dateOfReleving || null).format("DD-MM-YYYY") : "Present"})`}</div>
                                </h4>
                                {comp?.roles?.map((exp, idx) => (
                                    <div key={idx} className="d-flex justify-content-between mb-1">
                                        <div><strong>{exp.positionName}</strong></div>
                                        <div className="text-muted" style={{ fontSize: '14px' }}>
                                            {moment(exp.fromDate).format("DD-MM-YYYY")} to {moment(exp.toDate).format("DD-MM-YYYY")}
                                        </div>
                                    </div>
                                ))}
                            </div>
                        ))}
                    </div>
                </Row>

                {/* declaration */}
                <Row className="mt-3 mb-1">
                    <Col className="mx-4">
                        <p style={{ color: '#000', fontSize: '10px', marginBottom: '0' }}>
                            <span style={{ fontWeight: 'bold' }}>Declaration:</span>
                            <span style={{ marginLeft: '10px' }}>
                                The information displayed in this report is system-generated based on existing company data entries. It has not been manually edited or entered by company personnel. All content is derived from automated data processing to ensure consistency and accuracy.
                            </span>
                        </p>
                    </Col>
                </Row>

                {/* footer */}
                <div style={{ marginTop: '80px', padding: '10px' }}>
                    {footerFields.map((row, rowIndex) => (
                        <Row key={rowIndex} className="justify-between mb-2">
                            {row.map((col, colIndex) => (
                                <Col
                                    key={colIndex}
                                    className="text-center"
                                    style={{
                                        fontSize: '16px',
                                        color: 'black',
                                        fontWeight: 'bold',
                                        flex: 1,
                                        marginTop: '20px',
                                    }}>
                                    {col && <strong>{col}</strong>}
                                </Col>
                            ))}
                        </Row>
                    ))}
                </div>
            </div>

            {/* print design */}
            <Row className="d-print-none mt-4">
                <Col className="text-end">
                    <Link
                        to="#"
                        className="btn btn-dark me-1"
                        onClick={(e) => {
                            window.print();
                        }}>
                        <i className="fa fa-print"></i>
                    </Link>
                    {/* <Link to="#" className="btn btn-success me-1">
                        <i className="fa fa-download"></i> Download as PDF
                    </Link> */}
                </Col>
            </Row>

            <style>
                {`
                    @media print {
                        .page-break { 
                            page-break-before: always; 
                        }
                    }
                `}
            </style>
        </Container>
    );
}

export default Index;
